function tests(){
 const seen=new Set(attempts().filter(a=>a.chosen!==null).map(a=>a.id));
 const completed=PRACTICE_SETS.filter(s=>state.history.some(h=>h.setId===s.id));
 return title('MORE WAYS TO GROW','Your practice library.',`${PRACTICE_SETS.length} themed tests. ${BANK.length} original questions. A fresh challenge for your next session.`)+
 `<div class="library-summary"><div><b>${BANK.length-seen.size}</b><span>questions you haven’t tried</span></div><div><b>${completed.length} / ${PRACTICE_SETS.length}</b><span>themed tests completed</span></div><div><b>7 parts</b><span>in every themed test</span></div></div>
 <div class="section-head section-spacer"><h2>Ten themes. Ten fresh starts.</h2><div class="mode-control" role="group" aria-label="Test mode"><button class="pill ${testMode==='timed'?'selected':''}" data-test-mode="timed" aria-pressed="${testMode==='timed'}">Timed test</button><button class="pill ${testMode==='learning'?'selected':''}" data-test-mode="learning" aria-pressed="${testMode==='learning'}">Learning mode</button></div></div>
 <p class="sub" style="margin-bottom:20px">${testMode==='timed'?'20 minutes per test. Answers and explanations appear after submission.':'Go at your own pace. Check each answer and read its explanation immediately.'} The 10 themed tests contain 200 questions with no overlap between tests.</p>
 <div class="practice-grid">${PRACTICE_SETS.map(s=>{const runs=state.history.filter(h=>h.setId===s.id),best=runs.length?Math.max(...runs.map(h=>accuracy(h.answers))):null;const fresh=s.questions.filter(id=>!seen.has(id)).length;return `<article class="panel practice-card library-card"><div class="card-badges"><span class="badge">TEST ${String(s.id).padStart(2,'0')}</span><span class="set-status ${runs.length?'completed':''}">${runs.length?'Completed ✓':'Not completed'}</span></div><h3>${s.title}</h3><p>${s.topic}</p><small>20 questions · Parts 1–7 · ${testMode==='timed'?'20 min':'Untimed'}</small><div class="test-progress"><span>${fresh} questions untried</span><b>${best===null?'Ready when you are':`Best: ${best}%`}</b></div><button class="primary" data-start="set" data-part="${s.id}">${runs.length?'Practice again':'Start test '+String(s.id).padStart(2,'0')} <span>↗</span></button></article>`}).join('')}</div>
 <section class="panel section-spacer"><div class="eyebrow">YOUR OWN CHALLENGE</div><h2 style="margin:10px 0">Build a practice session</h2><p class="sub">Choose your length and focus. Questions you haven’t tried come first; older questions return when you run out of fresh ones.</p><form id="custom-test-form"><div class="custom-grid section-spacer"><label>Focus<select name="scope" aria-label="Focus"><option value="mixed">All seven parts</option><option value="listening">Listening · Parts 1–4</option><option value="reading">Reading · Parts 5–7</option></select></label><label>Session length<select name="count" aria-label="Session length"><option value="10">10 questions</option><option value="20" selected>20 questions</option><option value="30">30 questions</option><option value="50">50 questions</option></select></label><label>Mode<select name="mode" aria-label="Mode"><option value="timed">Timed · 1 minute per question</option><option value="learning">Learning · Untimed</option></select></label></div><button class="primary" type="submit" style="margin-top:22px">Create my practice session ↗</button></form></section>
 <div class="section-head section-spacer"><h2>Short on time? Start here.</h2></div><div class="practice-grid"><div class="panel practice-card"><span class="badge">STARTING POINT</span><h3>Quick skill check</h3><p>Two questions from each part. Discover what to focus on next.</p><small>14 questions · Untimed</small><button class="primary" data-start="diagnostic">Check my skills ↗</button></div><div class="panel practice-card"><span class="badge">MIXED CHALLENGE</span><h3>The 15-minute challenge</h3><p>A fresh mix from the full bank, with untried questions first.</p><small>20 questions · 15 minutes</small><button class="primary" data-start="timed">Start mini-test ↗</button></div><div class="panel practice-card"><span class="badge">READING SPRINT</span><h3>Read. Think. Decide.</h3><p>Focus on grammar, text completion, and finding evidence.</p><small>15 questions · 12 minutes</small><button class="primary" data-start="reading">Start reading sprint ↗</button></div></div>
 <p class="note">These are original educational mini-tests, not full-length official TOEIC exams. Listening uses synthetic speech; Part 1 uses illustrations. Practice percentages are not scaled TOEIC scores. <a href="https://www.ets.org/toeic/about/faq/product-specific-faq/toeic-listening-reading.html" class="link" target="_blank" rel="noopener">Official test information ↗</a></p>`;
}
function freshFirst(pool){const lastSeen=new Map();state.history.forEach((h,i)=>h.answers.forEach(a=>{if(a.chosen!==null)lastSeen.set(a.id,i+1)}));return shuffle(pool).sort((a,b)=>(lastSeen.get(a.id)||0)-(lastSeen.get(b.id)||0))}
function selectQuestions(pool,count){return freshFirst(pool).slice(0,count).sort((a,b)=>a.part-b.part||a.id-b.id)}
function renderQuiz(){renderQuizContent();if(quiz?.limit){$('#main .quiz-card').insertAdjacentHTML('beforeend',`<div class="question-navigator"><div class="eyebrow">JUMP TO A QUESTION</div><p class="note">Filled circles are answered. You can change answers before submitting.</p><div class="question-buttons">${quiz.questions.map((q,i)=>`<button class="question-dot ${quiz.answers[q.id]!==undefined?'answered':''} ${quiz.index===i?'current':''}" data-question-index="${i}" aria-label="Question ${i+1}${quiz.answers[q.id]!==undefined?', answered':''}" ${quiz.index===i?'aria-current="step"':''}>${i+1}</button>`).join('')}</div></div>`)}}
function balanced(count){const chosen=[];for(let p=1;p<=7;p++)chosen.push(...freshFirst(BANK.filter(q=>q.part===p)).slice(0,Math.min(2,Math.floor(count/7))));const ids=new Set(chosen.map(q=>q.id));return chosen.concat(freshFirst(BANK.filter(q=>!ids.has(q.id))).slice(0,count-chosen.length)).sort((a,b)=>a.part-b.part||a.id-b.id)}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.testMode){testMode=b.dataset.testMode;const position=window.scrollY;render();window.scrollTo(0,position)}if(b.dataset.questionIndex!==undefined&&quiz&&!quiz.checked){quiz.index=Number(b.dataset.questionIndex);stopAudio();renderQuiz()}});
document.addEventListener('submit',e=>{if(e.target.id!=='custom-test-form')return;e.preventDefault();const form=new FormData(e.target);start('custom',5,{scope:form.get('scope'),count:Number(form.get('count')),mode:form.get('mode')})});
